(7017394, 1063265, 83313, '<td valign="top">If it ain''t fixed, it''s broke.</td>', 'If it ain''t fixed, it''s broke.', '2013-04-10 01:05:50.000000', NULL, 1),
(7017399, 1063507, 18197, '<td valign="top">I used to ride Ducati and my daughter rides a Monster. Like this!</td>', 'I used to ride Ducati and my daughter rides a Monster. Like this!', '2013-04-10 01:06:41.000000', NULL, 1),
(7017403, 1062843, 83313, '<td valign="top">This brings to mind my younger daughter learning to ride a bike. The first time she rolled across the tennis courts on her own, then fell on her hands like this and it didn''t hurt. She was too excited over what she''s just done. She jumped up, pumping her fists up and down shouting "I DID IT, I DID IT!!!" Extra pointage for the blast from the past.</td>', 'This brings to mind my younger daughter learning to ride a bike. The first time she rolled across the tennis courts on her own, then fell on her hands like this and it didn''t hurt. She was too excited over what she''s just done. She jumped up, pumping her fists up and down shouting "I DID IT, I DID IT!!!" Extra pointage for the blast from the past.', '2013-04-10 01:08:25.000000', NULL, 1),
(7017404, 1062373, 30861, '<td valign="top">Absolutely gorgeous rendering of backlight, well done. One of the few times lately I''ve seen infrared used in a way that doesn''t shout "look how tricky I am!"</td>', 'Absolutely gorgeous rendering of backlight, well done. One of the few times lately I''ve seen infrared used in a way that doesn''t shout "look how tricky I am!"', '2013-04-10 01:09:22.000000', NULL, 1),
