(7018374, 1063223, 112539, '<td valign="top">Would have liked to see the rider better. Blends into the dark background. Think either the background could have gone darker or the man lighter in post processing.. Nice shot though.</td>', 'Would have liked to see the rider better. Blends into the dark background. Think either the background could have gone darker or the man lighter in post processing.. Nice shot though.', '2013-04-11 19:22:59.000000', NULL, 1),
(7018400, 1063453, 10785, '<td valign="top">Cute find. I like the framing here. I just think this is missing some contrast as there isn''t much indication of shadows or highlights. Because of that the image is lacking depth, appearing 2D.</td>', 'Cute find. I like the framing here. I just think this is missing some contrast as there isn''t much indication of shadows or highlights. Because of that the image is lacking depth, appearing 2D.', '2013-04-11 20:28:42.000000', NULL, 1),
(7018401, 1063233, 10785, '<td valign="top">Nice repetition here. The composition is great and I like the color pop! I do think that the image had an over abundance of denoise and topaz products applied to it though.</td>', 'Nice repetition here. The composition is great and I like the color pop! I do think that the image had an over abundance of denoise and topaz products applied to it though.', '2013-04-11 20:30:39.000000', NULL, 1),
(7018403, 1062984, 10785, '<td valign="top">I''m not sure what you are seeing here as being a subject of interest. Is it the lines, the shadows? Not sure.</td>', 'I''m not sure what you are seeing here as being a subject of interest. Is it the lines, the shadows? Not sure.', '2013-04-11 20:31:45.000000', NULL, 1),
(7018404, 1062778, 10785, '<td valign="top">I am not sure what you are seeing that captured your interest here. The composition is not leading me to anything in particular. There is much clutter to lok through.</td>', 'I am not sure what you are seeing that captured your interest here. The composition is not leading me to anything in particular. There is much clutter to lok through.', '2013-04-11 20:32:35.000000', NULL, 1),
(7018406, 1063230, 10785, '<td valign="top">After taking a second look at this, I am seeing the interesting abstract lines of the bike chain and tire. The little capture of the colored bike tubing adds some more interest.</td>', 'After taking a second look at this, I am seeing the interesting abstract lines of the bike chain and tire. The little capture of the colored bike tubing adds some more interest.', '2013-04-11 20:33:48.000000', NULL, 1),
